    static String users() {
        String content = """
                <h1>Users &amp; privileges</h1><p class="subtitle">Privonym application identities are independent from operating-system and database accounts.</p>
                <section class="panel"><h2 class="section-title">Create user</h2>
                  <div class="toolbar"><div class="form-field"><label for="user-username">Username</label><input id="user-username" maxlength="100"></div>
                    <div class="form-field"><label for="user-display-name">Display name</label><input id="user-display-name" maxlength="200"></div>
                    <div class="form-field"><label for="user-password">Initial password</label><input id="user-password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></div>
                    <label><input id="user-administrator" type="checkbox"> Administrator</label></div>
                  <p class="hint">Passwords require at least 12 characters with upper-case, lower-case, digit and special character.</p>
                  <div id="privilege-list" class="grid"></div>
                  <div class="toolbar" style="margin-top:18px"><button id="user-create" class="primary">Create user</button><span id="user-message" class="hint"></span></div>
                </section>
                <section class="panel"><h2 class="section-title">Application users</h2><div id="users-message" class="empty">Loading users…</div>
                  <table id="users-table" hidden><thead><tr><th>Username</th><th>Display name</th><th>Type</th><th>Status</th><th>Privileges</th><th>Actions</th></tr></thead><tbody></tbody></table></section>
                """;
        String script = """
                let usersPayload,editingUserId=null;const privilegeList=document.getElementById('privilege-list'),administrator=document.getElementById('user-administrator');
                function renderPrivileges(values){privilegeList.replaceChildren();values.forEach(code=>{const label=document.createElement('label');label.className='card';label.style.display='flex';label.style.alignItems='center';label.style.gap='10px';const input=document.createElement('input');input.type='checkbox';input.value=code;input.className='user-privilege';label.append(input,document.createTextNode(code.replaceAll('_',' ')));privilegeList.appendChild(label);});syncAdministrator();}
                function syncAdministrator(){document.querySelectorAll('.user-privilege').forEach(item=>{item.disabled=administrator.checked;if(administrator.checked)item.checked=true;});}
                administrator.addEventListener('change',syncAdministrator);
                async function loadUsers(){try{usersPayload=await json('/api/v1/security/users');renderPrivileges(usersPayload.availablePrivileges);const body=document.querySelector('#users-table tbody');body.replaceChildren();usersPayload.users.forEach(user=>{const row=document.createElement('tr');cell(row,user.username,'code');cell(row,user.displayName);cell(row,user.administrator?'Administrator':'Standard user');statusCell(row,user.enabled?'ENABLED':'DISABLED');cell(row,user.administrator?'All privileges':(user.privileges.join(', ')||'Read only'));const action=document.createElement('td'),edit=document.createElement('button'),button=document.createElement('button');edit.textContent='Edit privileges';edit.addEventListener('click',()=>editPrivileges(user));button.textContent=user.enabled?'Disable':'Enable';button.className=user.enabled?'logout':'';button.addEventListener('click',()=>setStatus(user,!user.enabled));action.append(edit,button);row.appendChild(action);body.appendChild(row);});document.getElementById('users-message').hidden=usersPayload.users.length>0;document.getElementById('users-table').hidden=!usersPayload.users.length;}catch(error){const message=document.getElementById('users-message');message.textContent=error.message;message.classList.add('error');}}
                function editPrivileges(user){editingUserId=user.id;document.getElementById('user-username').value=user.username;document.getElementById('user-username').disabled=true;document.getElementById('user-display-name').value=user.displayName;document.getElementById('user-display-name').disabled=true;document.getElementById('user-password').value='';document.getElementById('user-password').disabled=true;administrator.checked=user.administrator;document.querySelectorAll('.user-privilege').forEach(item=>item.checked=user.administrator||user.privileges.includes(item.value));syncAdministrator();document.getElementById('user-create').textContent='Save privileges';document.getElementById('user-message').textContent='Editing '+user.username;window.scrollTo({top:0,behavior:'smooth'});}
                function resetEditor(){editingUserId=null;document.getElementById('user-username').value='';document.getElementById('user-username').disabled=false;document.getElementById('user-display-name').value='';document.getElementById('user-display-name').disabled=false;document.getElementById('user-password').value='';document.getElementById('user-password').disabled=false;administrator.checked=false;document.getElementById('user-create').textContent='Create user';}
                async function setStatus(user,enabled){if(!confirm((enabled?'Enable ':'Disable ')+user.username+'?'))return;const response=await fetch('/api/v1/security/users/'+user.id+'/status',{method:'PUT',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body:new URLSearchParams({enabled})}),result=await response.json();if(!response.ok){showError(result.message||('HTTP '+response.status));return;}loadUsers();}
                document.getElementById('user-create').addEventListener('click',async()=>{const button=document.getElementById('user-create'),message=document.getElementById('user-message'),privileges=[...document.querySelectorAll('.user-privilege:checked')].map(item=>item.value),editing=editingUserId!==null;button.disabled=true;message.textContent=editing?'Saving privileges…':'Creating user…';message.classList.remove('error');try{const endpoint=editing?('/api/v1/security/users/'+editingUserId+'/privileges'):'/api/v1/security/users',method=editing?'PUT':'POST',parameters=editing?{administrator:administrator.checked,privileges:privileges.join(',')}:{username:document.getElementById('user-username').value.trim(),displayName:document.getElementById('user-display-name').value.trim(),password:document.getElementById('user-password').value,administrator:administrator.checked,privileges:privileges.join(',')};const response=await fetch(endpoint,{method,headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body:new URLSearchParams(parameters)}),result=await response.json();if(!response.ok)throw new Error(result.message||('HTTP '+response.status));message.textContent=editing?'Privileges saved for '+result.username+'.':'User '+result.username+' created.';resetEditor();await loadUsers();}catch(error){message.textContent=error.message;message.classList.add('error');}finally{button.disabled=false;}});loadUsers();
                """;
        return render("Users & privileges", "users", "Administration / Users & privileges", "", content, script);
    }

